export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const ticker = searchParams.get("ticker")
  const direction = searchParams.get("direction")
  const limit = parseInt(searchParams.get("limit") || "20")

  let results = ML_PREDICTIONS

  if (ticker) {
    results = results.filter(r => r.ticker.toLowerCase() === ticker.toLowerCase())
  }

  if (direction) {
    results = results.filter(r => r.direction === direction.toUpperCase())
  }

  results = results.slice(0, limit)

  return NextResponse.json({
    success: true,
    count: results.length,
    data: results,
    metadata: {
      models: ["LSTM", "SARIMAX", "Prophet", "XGBoost"],
      ensemble: "Ridge meta-model stacking",
      avg_directional_accuracy: "83.5%",
      avg_sharpe: 5.3,
      generated_at: "2025-03-01",
      total_stocks_analyzed: 497
    }
  })
}
